def pill(s):
    fnt = ImageFont.truetype(FM, 32, index=2); bb = fnt.getbbox(s)
    w, h = bb[2] - bb[0] + 40, bb[3] - bb[1] + 22
    im = Image.new('RGBA', (w, h), (0, 0, 0, 0)); d = ImageDraw.Draw(im)
    d.rounded_rectangle((0, 0, w - 1, h - 1), radius=h // 2, fill=(255, 205, 110, 235))
    d.text((20 - bb[0], 11 - bb[1]), s, font=fnt, fill=(60, 40, 10, 255)); return im
