    b1, b2 = f1.getbbox(term), f2.getbbox(defn)
    w = max(b1[2] - b1[0], b2[2] - b2[0]) + 70; h = 128
    im = Image.new('RGBA', (w, h), (0, 0, 0, 0)); d = ImageDraw.Draw(im)
    d.rounded_rectangle((0, 0, w - 1, h - 1), radius=22, fill=(8, 14, 24, 215), outline=(255, 205, 110, 255), width=3)
    d.rounded_rectangle((18, 18, 26, 58), radius=4, fill=(255, 205, 110, 255))
