NODE_L = {k: [text_img(x, FM, 26, (210, 215, 220), 2) for x in v] for k, v in NODESETS.items()}
NODE_LC = {k: [text_img(x, FB, 28, (255, 215, 130), 3) for x in v] for k, v in NODESETS.items()}
HUMAN = text_img('人类', FM, 26, (150, 155, 165), 2); TODAY = text_img('今天', FM, 26, (150, 155, 165), 2)
TX0, TSTEP, TY = 100, 150, 120

def timeline(img, cur, t, a, sweep=None, season=0):
    NL, NLC = NODE_L[season], NODE_LC[season]
    if a <= 0: return
    base = np.asarray(img, np.float32)
    band = base[60:185, :, :].mean()
    if band > 90:
        k = min(0.55, (band - 90) / 160) * a
        rows = np.arange(0, 240, dtype=np.float32)
        wgt = (np.clip((rows - 20) / 50, 0, 1) * np.clip((235 - rows) / 60, 0, 1))[:, None, None] * k
        arr = base.copy(); arr[0:240] = arr[0:240] * (1 - wgt) + np.array([12, 18, 24]) * wgt
        img.paste(Image.fromarray(arr.astype(np.uint8)))
    dr = ImageDraw.Draw(img)
    def c(col, k=1.0): return tuple(int(v * a * k) for v in col)
    xs = [TX0 + i * TSTEP for i in range(6)]
    end = xs[-1] + 140
    curx = xs[int(cur) - 1] if cur >= 1 else TX0
    dr.line((TX0, TY, end - 20, TY), fill=c((90, 100, 110)), width=3)
    dr.polygon([(end, TY), (end - 22, TY - 9), (end - 22, TY + 9)], fill=c((90, 100, 110)))
    if sweep is not None:
        sx = lerp(TX0, end, sweep); dr.line((TX0, TY, sx, TY), fill=c((255, 205, 110)), width=4)
        dr.ellipse((sx - 8, TY - 8, sx + 8, TY + 8), fill=c((255, 235, 180)))
    elif cur > 1:
        dr.line((TX0, TY, curx, TY), fill=c((255, 205, 110), 0.8), width=4)
    for i, x in enumerate(xs):
        n = i + 1
        if sweep is not None: done = x <= lerp(TX0, end, sweep); iscur = False
        else: done = n < cur; iscur = abs(n - cur) < 0.5
        if iscur:
            pr = 0.5 + 0.5 * math.sin(t * 3)
            dr.ellipse((x - 24 - 4 * pr, TY - 24 - 4 * pr, x + 24 + 4 * pr, TY + 24 + 4 * pr), outline=c((255, 205, 110), 0.6), width=3)
            dr.ellipse((x - 14, TY - 14, x + 14, TY + 14), fill=c((255, 205, 110)))
            put(img, NLC[i], x, TY + 50, a)
        elif done:
            dr.ellipse((x - 9, TY - 9, x + 9, TY + 9), fill=c((220, 175, 90)))
            put(img, NL[i], x, TY + 48, a * 0.8)
        else:
            dr.ellipse((x - 9, TY - 9, x + 9, TY + 9), fill=c((10, 14, 20)), outline=c((120, 130, 140)), width=3)
            put(img, NL[i], x, TY + 48, a * 0.5)
    put(img, TODAY if season >= 4 else HUMAN, end + 4, TY + 48, a * 0.7)

def blendimg(a, b, k):
    return Image.fromarray((np.asarray(a, np.float32) * (1 - k) + np.asarray(b, np.float32) * k).astype(np.uint8))
def dim(img, k):
    return img if k >= 0.999 else Image.fromarray((np.asarray(img, np.float32) * k).astype(np.uint8))

class Ep:
    def __init__(s, n):
        s.n = n; c = EPS[n]; s.c = c; s.mod = c['mod']; s.M = c['M']
        s.D = R + s.M + 8.5
        s.prev = EPS.get(n - 1)
        s.season = c.get('season', 0); s.idx = c.get('idx', n)
        s.caps = [(a + R, b + R, text_img(x, FM, 54)) for a, b, x in c['caps']]
        s.rcaps = [(a, b, text_img(x, FM, 54)) for a, b, x in c['recap_caps']]
        s.eras = [(a + R, min(b, s.M) + R, text_img(x, FL, 38, (230, 200, 160), 3)) for a, b, x in c['eras']]
        s.theme = text_img(c['theme'][0], FM, 54)
        s.cards = [(a + R, b + R, make_card(x, y)) for a, b, x, y in c.get('cards', [])]
        s.scales = [(a + R, min(b, s.M) + R, scale_pill(x)) for a, b, x in c.get('scale', [])]
        s.T_SERIES = text_img('38 亿年家谱', FB, 110, (255, 220, 170), 6)
        s.T_EP = text_img(f'第二部 · 人类社会 · 第 {s.idx} 集' if s.season >= 4 else f'第 {s.season} 季 · {SNAME[s.season][0]}第 {s.idx} 集', FM, 46, (220, 220, 220), 3)
        s.T_NAME = text_img(c['title'], FB, 80, (255, 255, 255), 5)
        s.T_N1 = text_img(c.get('next_label', '下一集'), FM, 48, (220, 220, 220), 3)
        s.T_N2 = text_img(c['next'], FB, 96, (255, 225, 160), 6)

    def visual(s, t):
        if t < R:
            if s.prev is None: v = Image.fromarray(np.clip(bg * ss(0, 1.0, t), 0, 255).astype(np.uint8))
            else: v = s.prev['mod'].render(s.prev['M'] + 4.5 + t)
            if t > R - XF: v = blendimg(v, s.mod.render(0.0), ss(R - XF, R, t))
            return v
        return s.mod.render(t - R)

    def frame(s, t):
        img = s.visual(t)
        tm = t - R
        ta = fade_win(tm, 1.0, 6.0, 0.7) if 0 <= tm < 6.5 else 0
        endk = ss(s.M + 4.4, s.M + 5.0, tm)
        img = dim(img, (1 - 0.55 * ta) * (1 - 0.55 * endk) * (1 - ss(s.D - 0.6, s.D, t)))
        # timeline
        if s.prev is None and t < R:
            timeline(img, 0, t, ss(0.3, 1.0, t), sweep=ss(1.2, 6.0, t))
        else:
            timeline(img, s.idx if (s.prev is None or t >= R - 0.3) else s.idx - 1, t, 1.0, season=s.season)
        for a, b, im in s.eras:
            if a <= t <= b: put(img, im, W / 2, 255, fade_win(t, a, b, 0.6))
        for a, b, im in s.scales:
            if a <= t <= b: put(img, im, W / 2, 316, fade_win(t, a, b, 0.5))
        for a, b, im in s.cards:
            if a <= t <= b: put(img, im, W / 2, 430, fade_win(t, a, b, 0.4))
        # recap
        if t < R:
            tag = P_PRO if s.prev is None else P_RECAP
            put(img, tag, W / 2, 1572, fade_win(t, 0.3, R - 0.2, 0.4))
            for a, b, im in s.rcaps:
                if a <= t <= b: put(img, im, W / 2, 1660, fade_win(t, a, b, 0.3))
        put(img, s.T_SERIES, W / 2, 760, ta); put(img, s.T_EP, W / 2, 880, ta)
        put(img, s.T_NAME, W / 2, 1010, fade_win(tm, 2.2, 6.0, 0.7) if 0 <= tm < 6.5 else 0)
        for a, b, im in s.caps:
            if a <= t <= b: put(img, im, W / 2, 1660, fade_win(t, a, b, 0.35))
        th = fade_win(tm, s.M + 0.2, s.M + 4.3, 0.4)
        put(img, P_THEME, W / 2, 1572, th); put(img, s.theme, W / 2, 1660, th)
        na = fade_win(tm, s.M + 4.6, s.M + 8.6, 0.5) * (1 - ss(s.D - 0.6, s.D, t))
        put(img, s.T_N1, W / 2, 1500, na); put(img, s.T_N2, W / 2, 1610, na)
        return img

    def audio(s, path):
        n = int(s.D * SR); t = np.arange(n) / SR
        cur = np.load(f'bed{s.n}.npy')
        bed = np.zeros(n, np.float32)
        main = cur[:int((s.M + 8.5) * SR)]; st = int(R * SR)
        bed[st:st + main.size] += main[:n - st]
        if s.prev is None: rec = cur[:st] * 0.7
        else:
            pb = np.load(f'bed{s.n - 1}.npy'); p0 = int((s.prev['M'] + 4.5) * SR); rec = pb[p0:p0 + st]
        xf = int(XF * SR)
        w = np.ones(st); w[st - xf:] = np.linspace(1, 0, xf)
        bed[:st] += rec * w
        bed[st - xf:st] += cur[:xf] * np.linspace(0, 1, xf) if s.prev is not None else 0
        vo = np.zeros(n, np.float32)
        intro = f'三十八亿年家谱，第二部，人类社会，第{NUM[s.idx]}集，{s.c["title"]}。' if s.season >= 4 else f'三十八亿年家谱，第{SNUM[s.season]}季，{SNAME[s.season][1]}第{NUM[s.idx]}集，{s.c["title"]}。'
        lines = list(s.c['recap_vo']) + [(R + 1.3, intro)]
        lines += [(a + R, x) for a, x in s.c['vo']]
        lines += [(R + s.M + 0.3, s.c['theme'][1]), (R + s.M + 4.8, s.c.get('next_vo', f'下一集，{s.c["next"]}。'))]
        for t0, x in lines:
            a = tts(x); i0 = int(t0 * SR); i1 = min(i0 + a.size, n); vo[i0:i1] += a[:i1 - i0]
        venv = np.convolve(np.abs(vo), np.ones(int(0.25 * SR)) / int(0.25 * SR), 'same')
        duck = 1 - 0.5 * np.clip(venv / 0.05, 0, 1)
        mix = bed * duck + vo
        mix *= np.clip(t / 0.6, 0, 1) * np.clip((s.D - t) / 1.2, 0, 1)
        mix = np.tanh(mix * 1.1) / np.tanh(1.1); mix = mix / np.abs(mix).max() * 0.95
        with wave.open(path, 'wb') as wv:
            wv.setnchannels(1); wv.setsampwidth(2); wv.setframerate(SR); wv.writeframes((mix * 32767).astype(np.int16).tobytes())
        return lines

TB = glob.glob('dl/bin/*/bin')[0]; TLIB = glob.glob('dl/bin/*/lib')[0]
TM = [d for d in glob.glob('dl/model/*') if os.path.isdir(d)]; TM = TM[0] if TM else 'dl/model'
def tts(text):
    os.makedirs('vo_cache', exist_ok=True)
    h = hashlib.md5(text.encode()).hexdigest()[:12]; npy = f'vo_cache/{h}.npy'
    if os.path.exists(npy): return np.load(npy)
    p = f'vo_cache/{h}.wav'; q = f'vo_cache/{h}_44.wav'
    subprocess.run([f'{TB}/sherpa-onnx-offline-tts', f'--vits-model={TM}/model.onnx', f'--vits-lexicon={TM}/lexicon.txt',
                    f'--vits-tokens={TM}/tokens.txt', f'--vits-dict-dir={TM}/dict', '--sid=1', f'--output-filename={p}', text],
                   env=dict(os.environ, LD_LIBRARY_PATH=TLIB), check=True, capture_output=True)
    subprocess.run(['ffmpeg', '-y', '-v', 'error', '-i', p, '-ar', str(SR), '-ac', '1', q], check=True)
    with wave.open(q) as w: a = np.frombuffer(w.readframes(w.getnframes()), np.int16).astype(np.float32) / 32768
    a = a / (np.abs(a).max() + 1e-6) * 0.9; np.save(npy, a); return a

if __name__ == '__main__':
    n = int(sys.argv[1]); e = Ep(n)
    if sys.argv[2] == 'stills':
        for ts in sys.argv[3:]: e.frame(float(ts)).save(f's{n}_{ts}.png')
    elif sys.argv[2] == 'audio':
        lines = e.audio(f's{n}.wav')
        for i, (t0, x) in enumerate(lines):
            nx = lines[i + 1][0] if i + 1 < len(lines) else e.D
            print(f'{t0:5.1f} {tts(x).size / SR:4.1f}/{nx - t0:4.1f} {x}')
    else:
        out = sys.argv[3]
        if not os.path.exists(f's{n}.wav'): e.audio(f's{n}.wav')
        p = subprocess.Popen(['ffmpeg', '-y', '-loglevel', 'error', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-s', f'{W}x{H}',
                              '-r', str(FPS), '-i', '-', '-i', f's{n}.wav', '-c:v', 'libx264', '-preset', 'medium', '-crf', '19',
                              '-pix_fmt', 'yuv420p', '-af', 'loudnorm=I=-14:TP=-1.5:LRA=11', '-ar', '44100', '-c:a', 'aac',
                              '-b:a', '160k', '-ac', '2', '-shortest', '-movflags', '+faststart', out], stdin=subprocess.PIPE)
        nf = int(e.D * FPS)
        for i in range(nf):
            p.stdin.write(e.frame(i / FPS).tobytes())
            if i % 300 == 0: print(i, nf, flush=True)
        p.stdin.close(); p.wait(); print('done')
